['You (Candidate)', q{Draft one, in my head first. <strong>Sentence one, recall:</strong> name the moment that actually happened — <em>"Grace, your question about mentoring under delivery pressure stayed with me on the train home."</em> Specific beats polite.}, q{先在脑子里起草。<strong>第一句，回顾：</strong>点名真实发生的瞬间——<em>"Grace，你关于交付压力下带人的问题，我在回家火车上一直在想。"</em>具体胜过客套。}],
['You (Candidate)', q{<strong>Sentence two, value:</strong> attach that moment to what I bring — <em>"it sharpened how I would pitch my first-quarter plan: pairing rotations for the two mid-level engineers before any process change."</em> <strong>The recall is not decoration; it becomes a deliverable.</strong>}, q{<strong>第二句，价值：</strong>把那个瞬间接到我能带来的东西上——<em>"它让我把第一季度计划想得更清楚：在任何流程变更之前，先为两位中级工程师做结对轮换。"</em><strong>回顾不是装饰，它要变成可交付物。</strong>}],
['You (Candidate)', q{<strong>Sentence three, miss-fix:</strong> the answer I want to improve. Tomas asked about event-driven trade-offs and I rambled. <em>"Tomas, on your event-driven question — my fuller answer is that we would start with the two flows where replay matters (payments and onboarding), and keep CRUD paths synchronous."</em> <strong>One improved answer, not a re-interview.</strong>}, q{<strong>第三句，补丁：</strong>想改进的那个回答。Tomas 问事件驱动取舍时我讲散了。<em>"Tomas，关于事件驱动——更完整的回答是：先在回放价值最高的两条流程（支付与开户）上落地，CRUD 路径保持同步。"</em><strong>一个改进的答案，不是重考一遍。</strong>}],
['You (Candidate)', q{<strong>Sentence four, fit:</strong> why this team, in their words — <em>"Anita\'s point about ownership culture is exactly the environment where my style works: explicit owners, written decisions."</em> <strong>Sentence five, logistics:</strong> <em>"Happy to provide references or anything else useful — looking forward to your timeline."</em>}, q{<strong>第四句，匹配：</strong>用他们的话说为什么是这个团队——<em>"Anita 说的 owner 文化正是我这种风格适合的环境：明确的责任人、书面的决定。"</em><strong>第五句，流程：</strong><em>"如需推荐人或其他材料随时说——期待你的时间表。"</em>}],
['You (Candidate)', q{Now the discipline pass. <strong>No "I am excited to leverage my synergies."</strong> No paragraph about the company from its own website. <strong>Five sentences, specific, sent within 24 hours — to Grace, naming Tomas and Anita.</strong> Read it once as if I were Grace: <em>does every sentence earn its place?</em> Send.}, q{然后是纪律检查。<strong>不写"我很兴奋能发挥我的协同效应"。</strong>不写从官网抄来的公司介绍。<strong>五句话、具体、24 小时内——发给 Grace，点名 Tomas 和 Anita。</strong>以 Grace 的视角读一遍：<em>每句话都挣到了自己的位置吗？</em>发送。}],
],
phrases => [
['Recall', q{Your question about … stayed with me on the train home.}, q{你关于……的问题，我在回家路上一直在想。}, q{"Stayed with me" marks genuine impact — generic flattery cannot fake the specific moment.}],
['Value', q{It sharpened how I would pitch my first-quarter plan: …}, q{它让我把第一季度计划想得更清楚：……}, q{Attach every recall to a deliverable — memory becomes plan, plan becomes evidence.}],
['Miss-fix', q{My fuller answer is that…}, q{更完整的回答是……}, q{The graceful way to redo a ramble: fuller, not corrected. One improved answer per email, maximum.}],
['Fit', q{In their words: "ownership culture" — exactly where my style works.}, q{用他们的话说："owner 文化"——正是我风格适配的环境。}, q{Quoting their vocabulary back proves listening and locks fit in their own language.}],
['Logistics', q{Happy to provide references — looking forward to your timeline.}, q{推荐人或其他材料随时说——期待你的时间表。}, q{Ends cooperative and concrete; "your timeline" gently asks for the date without demanding it.}],
['Discipline', q{Does every sentence earn its place?}, q{每句话都挣到了自己的位置吗？}, q{The editing test for a five-sentence email — anything that fails it, cut.}],
],
vocab => [
['Thank-you email', 'n. 感谢邮件', 'The 24-hour follow-up after an interview — short, specific, useful.'],
['Recall', 'n. 回顾', 'A specific moment from the interview, named — the anti-template move.'],
['Miss-fix', 'n. 补丁', 'One improved answer to a question you fumbled.'],
['Chair', 'n. 主持面试官', 'The panel lead — addressee of the email, mention others by name.'],
['Deliverable', 'n. 可交付物', 'Something concrete you would produce — plans beat enthusiasm.'],
['First-quarter plan', 'n. 首季度计划', 'What you would do in the first 90 days — the email\'s best payload.'],
['Synergy talk', 'n. 空洞套话', 'Corporate filler language — the failure mode of thank-you emails.'],
['Timeline', 'n. 时间表', 'When the decision comes; ask lightly, hold firmly.'],
],
grammar => [
['Past simple for the moment, present for the meaning', q{<em>"Your question about mentoring stayed with me"</em> — past simple for the interview moment; <em>"it sharpens how I would pitch…"</em> — present simple for what it does now. The tense shift IS the email\'s logic: the event is finished, its value is current. Candidates who blur the tenses blur the message.}, q{"Your question about mentoring stayed with me"——过去时讲面试瞬间；"it sharpens how I would pitch…"——现在时讲它此刻的作用。时态切换就是这封邮件的逻辑：事件已结束，价值在进行时。时态含糊，信息就含糊。}],
['"My fuller answer is that…" — the repair frame', q{<em>"My fuller answer is that we would start with the two flows where replay matters."</em> — <strong>fuller</strong>, not "more correct": it frames the follow-up as added depth, never as self-correction. The frame is <strong>[my fuller answer is that] + [one dense sentence]</strong>. One per email; two reads as insecurity.}, q{"My fuller answer is that…"——用 <strong>fuller</strong> 而不是"更正确"：把补丁定位为补充深度，而非自我纠错。句式：<strong>[my fuller answer is that] + [一句高密度的话]</strong>。每封一处；两处显得不自信。}],
],
tips => [
q{<strong>24 hours, to the chair, by name for the others.</strong> Faster reads anxious; later reads forgetful.}
,
q{<strong>Five sentences, five jobs.</strong> Recall, value, miss-fix, fit, logistics. If a sentence does none of these, it is filler — cut it.},
q{<strong>The miss-fix is the highest-scoring sentence.</strong> Improving an answer after the room shows exactly the growth habit the job needs.},
q{<strong>Use their vocabulary.</strong> "Ownership culture", "release confidence" — their words, not the website\'s.},
q{<strong>Never attach your CV again.</strong> They have it. Attach nothing; the email is the artifact.},
],
practice => [
{ t => 'Draft yours now', p => 'Write your five sentences for your most recent interview: recall, value, miss-fix, fit, logistics. Then delete every sentence that does not do its job.', a => q{Read it as the chair would: does sentence one prove you were present? Does sentence three show growth without grovelling? If the email survives both questions, send it within 24 hours.} },
{ t => 'Fix the broken email', p => 'What makes this thank-you fail?', b => q{<blockquote>"Dear Grace, Thank you so much for the opportunity to interview for this exciting role. I am very excited about the position and confident my skills and experience make me a strong fit. I look forward to hearing from you. Best regards."</blockquote>}, a => q{Zero specifics: no moment recalled, no name but the chair, no deliverable, no miss-fix. It is a form letter that could have been sent to any company — and panels receive fifty of them. Replace every abstract noun (opportunity, exciting, skills) with something that happened yesterday.} },
{ t => 'The miss-fix sentence', p => 'You rambled when asked about cost estimation. Write your one-sentence fuller answer, using the repair frame.', a => q{"Tomas, on estimation — my fuller answer is that I estimate in ranges with confidence levels, re-baseline at every scope change, and treat the first number as a communication device, not a commitment." Fuller, denser, no apology.} },
],
},
{
num => 14, slug => 'following-up-status', module => 4, read => 6, diff => '🟢 Beginner-friendly',
title => 'Following Up on the Timeline', cn => '进度跟进',
focus => 'Chase politely past the silence: date-anchored, low-pressure, doors open',
scenario => [
q{The interview was <strong>ten days ago</strong>. Grace said, <em>"Decision this week, feedback by Friday."</em> It is now the following Wednesday. Two more days of silence and you will start imagining things. <strong>The follow-up email you write today is a work sample too</strong> — banks notice how people chase.},
q{面试是 <strong>10 天前</strong>的事。Grace 说过：<em>"本周定，周五前反馈。"</em>现在已是下周三。再沉默两天你就要开始胡思乱想了。<strong>今天要写的跟进邮件同样是一份工作样本</strong>——银行会注意一个人怎么"催"。},
q{The craft is chasing without pressure: <strong>anchor to their date, not your anxiety</strong>; ask for a status, not a verdict; and keep every door — including the "you were slow" door — firmly closed in the text.},
q{技巧在于"催而不压"：<strong>锚定他们的日期，而不是你的焦虑</strong>；问的是进度，不是判决；并且把所有情绪（包括"你们太慢了"）牢牢挡在文本之外。},
],
dialogue => [
['You (Candidate)', q{Draft rules, before I write. <strong>Rule one: anchor to their date.</strong> Grace said Friday — so my first line references that promise, not my mood: <em>"you mentioned feedback by last Friday."</em>}, q{动笔前先立规矩。<strong>规则一：锚定他们的日期。</strong>Grace 说过周五——所以第一句引用那个承诺，而不是我的心情：<em>"你提到上周五会给反馈。"</em>}],
['You (Candidate)', q{<strong>Rule two: ask for status, not verdict.</strong> <em>"Is the process still on track, and is there anything useful from my side?"</em> — the second half makes it easy to reply with a task instead of a decision. <strong>Recruiters answer emails that contain a small ask; they avoid emails that demand one.</strong>}, q{<strong>规则二：问进度，不要判决。</strong><em>"流程是否仍在推进，我这边有什么能帮上忙的吗？"</em>——后半句让对方可以回一个小任务而不是一个决定。<strong>招聘者会回复包含小请求的邮件；会回避索要决定的邮件。</strong>}],
['You (Candidate)', q{<strong>Rule three: one channel, one message.</strong> No LinkedIn nudge, no second email tomorrow, no call. <strong>Silence for five working days after this one</strong> — then one more, then I redirect my energy to other loops. <em>Desperation has a smell; discipline is the cologne.</em>}, q{<strong>规则三：一个渠道，一条信息。</strong>不领英私信、明天不补发、不打电话。这条之后<strong>再静默五个工作日</strong>——然后最多再一条，之后把精力转向其他流程。<em>绝望有味道；纪律才是香水。</em>}],
['You (Candidate)', q{The email itself. Subject: <strong>"Following up — [Role] interview, [date]"</strong> — the role in the subject because Priya runs twelve loops and memory is a kindness. Body, four sentences: recall the date, reference their timeline, status question with the small ask, <strong>warm close that re-states interest once</strong>.}, q{邮件本身。主题：<strong>"Following up — [岗位] 面试，[日期]"</strong>——主题里带岗位，因为 Priya 同时管着十二个流程，帮对方省记忆是一种善意。正文四句：回顾日期、引用他们的时间线、带小请求的进度提问、<strong>重申一次兴趣的温暖收尾</strong>。}],
['You (Candidate)', q{Read before sending, in Priya\'s voice: <em>does this email make my day easier or harder?</em> Four sentences, zero guilt, one small ask. <strong>Send — and close the laptop.</strong>}, q{发送前用 Priya 的语气读一遍：<em>这封邮件让我的今天更轻松还是更沉重？</em>四句话、零愧疚感、一个小请求。<strong>发送——然后合上电脑。</strong>}],
],
phrases => [
['Anchor', q{You mentioned feedback by last Friday.}, q{你提到上周五会给反馈。}, q{Their promise, quoted back neutrally — facts without accusation.}],
['Ask', q{Is the process still on track?}, q{流程是否仍在推进？}, q{"Still on track" assumes a process, not a verdict — status, not pressure.}],
['Enable', q{Is there anything useful from my side?}, q{我这边有什么能帮上忙的吗？}, q{The small ask that makes replying easy — references, documents, a slot.}],
['Cadence', q{One channel, one message, five working days.}, q{一个渠道、一条信息、五个工作日。}, q{The follow-up cadence — discipline the recruiter can feel through the screen.}],
['Close', q{The role remains very attractive to me.}, q{这个岗位对我仍然非常有吸引力。}, q{Interest re-stated exactly once — enough to warm, not enough to weigh.}],
['Mindset', q{Desperation has a smell; discipline is the cologne.}, q{绝望有味道，纪律才是香水。}, q{A memorable one-liner — write it somewhere you will see it during the silence.}],
],
vocab => [
['On track', 'phr. 按计划推进', 'Process moving as planned — the status you are asking about.'],
['Loop', 'n. 招聘流程', 'One hiring process; good candidates run several in parallel.'],
['Nudge', 'n. 轻推', 'A low-value repeated ping — what you must not do.'],
['Cadence', 'n. 节奏', 'The rhythm of your follow-ups: one message, then patience.'],
['Subject line', 'n. 邮件主题', 'Where recall lives: role, date — kindness to a busy inbox.'],
['Guilt-trip', 'n. 愧疚绑架', 'Pressuring through blame — the fastest way out of a shortlist.'],
['Shortlist', 'n. 候选名单', 'The small set still in contention; protect your place in it.'],
['Silence', 'n. 沉默', 'Not a verdict. It is logistics, holidays, and busy calendars.'],
